// interest_lite.js — 个人兴趣模型·轻量轨（浏览器内，零安装）
// 用法: IM.ingest({t:标题, u:作者, type:"expose"|"click"|"watch", dwell:秒}); IM.profile(); IM.setPref(主题名, -2..2)
// 数据只存 localStorage（键 im_lite_*），与 eval/profile_engine.py 同一套数学。
(function (root) {
  "use strict";
  const TOPICS = ["编程与软件开发", "人工智能", "硬件与数码评测", "科技产业资讯", "科学科普", "数学与物理", "历史人文", "社科心理与法律", "语言学习", "学习方法与校园", "职场与技能", "宏观经济与投资", "商业分析与创业", "单机与主机游戏", "网游与电竞", "手机游戏", "游戏杂谈与攻略", "番剧与动漫", "国创动画", "鬼畜", "虚拟主播", "影视解说", "电影与预告", "综艺与明星", "短剧与剧情演绎", "演奏与翻唱", "原创音乐", "舞蹈", "美食制作", "探店与吃播", "旅行户外", "家居手工与DIY", "时尚美妆", "汽车", "萌宠动物", "自然植物", "体育赛事", "健身与运动教学", "健康养生", "生活Vlog", "情感与人际", "纪录片", "访谈与演讲", "时事资讯", "社会观察", "搞笑段子", "猎奇与整活", "营销与带货"];
  const GROUPS = {"科技数码": ["编程与软件开发", "人工智能", "硬件与数码评测", "科技产业资讯"], "知识学习": ["科学科普", "数学与物理", "历史人文", "社科心理与法律", "语言学习", "学习方法与校园", "职场与技能"], "财经商业": ["宏观经济与投资", "商业分析与创业"], "游戏": ["单机与主机游戏", "网游与电竞", "手机游戏", "游戏杂谈与攻略"], "动画二次元": ["番剧与动漫", "国创动画", "鬼畜", "虚拟主播"], "影视娱乐": ["影视解说", "电影与预告", "综艺与明星", "短剧与剧情演绎"], "音乐舞蹈": ["演奏与翻唱", "原创音乐", "舞蹈"], "生活方式": ["美食制作", "探店与吃播", "旅行户外", "家居手工与DIY", "时尚美妆", "汽车", "萌宠动物", "自然植物"], "运动健康": ["体育赛事", "健身与运动教学", "健康养生"], "日常记录": ["生活Vlog", "情感与人际"], "纪实深度": ["纪录片", "访谈与演讲"], "资讯社会": ["时事资讯", "社会观察"], "泛娱乐": ["搞笑段子", "猎奇与整活", "营销与带货"]};
  const CFG = { dims: 8192, scale: 0.10017391294240952, hlShort: 7 * 86400e3, hlLong: 90 * 86400e3 };
  const BIAS = [-0.013453, -0.94507, 0.645409, 0.556743, 0.325848, -0.661587, 0.413775, 0.091924, -1.162654, -0.406726, -1.023862, -0.449862, -0.867902, 0.237289, 0.679065, 1.440755, 0.270555, 0.168466, -0.122105, -0.68058, 0.012866, 0.713704, -0.462842, 0.731784, -0.139642, 0.680739, -0.332876, -0.092533, 0.372423, 0.577944, 0.138467, 0.456703, 0.71412, -0.638246, 0.045545, -1.159613, -0.01487, -0.034258, 0.143633, -0.210066, -0.644217, -1.105403, 0.31954, 0.837502, 0.069696, 0.519086, -0.375529, 0.380315];
  const W = (() => { const bin = atob(""); const w = new Int8Array(bin.length); for (let i = 0; i < bin.length; i++) w[i] = (bin.charCodeAt(i) << 24) >> 24; return w; })();
  function mmh3(bytes) {
    const c1 = 0xcc9e2d51, c2 = 0x1b873593;
    let h = 0;
    const n = bytes.length - (bytes.length % 4);
    for (let i = 0; i < n; i += 4) {
      let k = (bytes[i] | (bytes[i + 1] << 8) | (bytes[i + 2] << 16) | (bytes[i + 3] << 24)) >>> 0;
      k = Math.imul(k, c1); k = (k << 15) | (k >>> 17); k = Math.imul(k, c2);
      h ^= k; h = (h << 13) | (h >>> 19); h = (Math.imul(h, 5) + 0xe6546b64) >>> 0;
    }
    let k = 0;
    const t = bytes.length % 4;
    if (t >= 3) k ^= bytes[n + 2] << 16;
    if (t >= 2) k ^= bytes[n + 1] << 8;
    if (t >= 1) { k ^= bytes[n]; k = Math.imul(k >>> 0, c1); k = (k << 15) | (k >>> 17); k = Math.imul(k, c2); h ^= k; }
    h ^= bytes.length;
    h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b);
    h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35);
    h ^= h >>> 16;
    return h | 0;
  }
  const enc = new TextEncoder();
  function proba(title, up) {
    const s = (String(title || "") + " \x01 " + String(up || "")).toLowerCase().replace(/\s\s+/g, " ");
    const chars = Array.from(s);
    const counts = new Map();
    for (let n = 1; n <= 3; n++)
      for (let i = 0; i + n <= chars.length; i++) {
        const idx = Math.abs(mmh3(enc.encode(chars.slice(i, i + n).join("")))) % CFG.dims;
        counts.set(idx, (counts.get(idx) || 0) + 1);
      }
    let norm = 0;
    for (const v of counts.values()) norm += v * v;
    norm = Math.sqrt(norm) || 1;
    const z = BIAS.slice();
    for (const [idx, c] of counts) {
      const cv = c / norm;
      for (let t = 0; t < 48; t++) z[t] += W[t * CFG.dims + idx] * CFG.scale * cv;
    }
    const m = Math.max(...z);
    let sum = 0;
    const e = z.map(v => { const x = Math.exp(v - m); sum += x; return x; });
    return e.map(v => v / sum);
  }
  const LSK = "im_lite_state";
  function load() {
    try { const d = JSON.parse(localStorage.getItem(LSK)); if (d && d.short) return d; } catch (e) {}
    return { short: new Array(48).fill(0), long: new Array(48).fill(0), expose: new Array(48).fill(0), ts: null, prefs: {}, n: 0 };
  }
  const S = load();
  let saveTimer = null;
  const save = () => { clearTimeout(saveTimer); saveTimer = setTimeout(() => { try { localStorage.setItem(LSK, JSON.stringify(S)); } catch (e) {} }, 1500); };
  function decay(now) {
    if (S.ts !== null) {
      const dt = Math.max(0, now - S.ts);
      const fs = Math.pow(0.5, dt / CFG.hlShort), fl = Math.pow(0.5, dt / CFG.hlLong);
      for (let i = 0; i < 48; i++) { S.short[i] *= fs; S.long[i] *= fl; S.expose[i] *= fl; }
    }
    S.ts = now;
  }
  function ingest(ev) {
    const now = ev.ts || Date.now();
    decay(now);
    const p = proba(ev.t, ev.u);
    const w = ev.type === "expose" ? 1 : ev.type === "click" ? 5 : 5 + Math.min((ev.dwell || 0) / 60, 10);
    for (let i = 0; i < 48; i++) {
      if (ev.type === "expose") S.expose[i] += p[i];
      else { S.short[i] += w * p[i]; S.long[i] += w * p[i]; }
    }
    S.n++;
    save();
  }
  const nz = v => { const s = v.reduce((a, b) => a + b, 0); return s > 0 ? v.map(x => x / s) : v.slice(); };
  function profile() {
    return { topics: TOPICS, groups: GROUPS, short: nz(S.short), long: nz(S.long), expose: nz(S.expose), prefs: S.prefs, n: S.n };
  }
  function setPref(topic, v) { if (TOPICS.includes(topic)) { S.prefs[topic] = Math.max(-2, Math.min(2, v)); save(); } }
  // 兴趣加成分：给下游（排序/过滤）用——申明偏好覆盖行为倾向
  function affinity(title, up) {
    const p = proba(title, up);
    const lg = nz(S.long);
    let a = 0;
    for (let i = 0; i < 48; i++) {
      const pref = S.prefs[TOPICS[i]] || 0;
      a += p[i] * (lg[i] + 0.5 * pref);
    }
    return a;
  }
  const IM = { ingest, profile, setPref, affinity, proba,
    exportState: () => JSON.stringify(S),
    importState: (s) => { try { const d = JSON.parse(s); Object.assign(S, d); save(); return true; } catch (e) { return false; } } };
  if (typeof module !== "undefined") module.exports = IM;
  else root.IM = IM;
})(typeof window !== "undefined" ? window : globalThis);
